async function commit(change,{backup=true,render=true}={}){
  clearTimeout(draftTimer);let writing=false;
  const task=saveQueue.then(async()=>{
    if(!state||storageError)throw Error(storageError||'请先恢复本机数据。');
    const next=structuredClone(state);change(next);validateState(next);status('保存中…');writing=true;
    const saved=await saveStorage(next,state.revision,{backup});
    if(!backup){saved.draft=structuredClone(state.draft);if(state.workbench)saved.workbench=structuredClone(state.workbench);}
    state=saved;status('已保存至本机');if(render)renderAll();return saved;
  });
  saveQueue=task.catch(e=>{if(writing||e instanceof DataConflict)showStorageError(e.message);});
  return task;
}
