function renderChart(curve){
  if(!curve.latest){$('#equity-chart').innerHTML=empty('权益曲线等待真实快照','初始资金规则不是账户历史，尚无数据计算最大回撤。');return;}
  const ps=curve.points,w=920,h=210,pad=30,lo=Math.min(...ps.map(p=>p.normalized)),hi=Math.max(...ps.map(p=>p.normalized)),range=hi-lo||Math.max(100,hi*.04),min=lo-range*.1,max=hi+range*.1;
  const points=ps.map((p,i)=>[pad+i*(w-pad*2)/Math.max(1,ps.length-1),pad+(max-p.normalized)/(max-min)*(h-pad*2)]),line=points.map(([x,y],i)=>(i?'L':'M')+x.toFixed(2)+','+y.toFixed(2)).join(' ');
  $('#equity-chart').innerHTML=`<svg class="equity-svg" viewBox="0 0 ${w} ${h}" role="img" aria-label="账户权益曲线"><title>出入金调整后的权益，最大回撤 ${pct(curve.maxDD)}</title>${[0,.5,1].map(t=>{const y=pad+t*(h-pad*2);return `<line x1="${pad}" x2="${w-pad}" y1="${y}" y2="${y}" stroke="var(--line)"/>`;}).join('')}<path d="${line}" fill="none" stroke="var(--accent)" stroke-width="2"/>${points.map(([x,y],i)=>`<circle cx="${x}" cy="${y}" r="3" fill="var(--accent)"><title>${esc(date(ps[i].at))} · ${money(ps[i].normalized)} · 回撤 ${pct(ps[i].drawdown)}</title></circle>`).join('')}</svg>`;
}
