function route(){let id=location.hash.slice(1);if(!routes[id])id='workspace';$$('.page').forEach(e=>e.hidden=e.id!=='page-'+id);$$('[data-route]').forEach(e=>{e.classList.toggle('active',e.dataset.route===id);if(e.dataset.route===id)e.setAttribute('aria-current','page');else e.removeAttribute('aria-current');});$('#page-label').textContent=routes[id];document.title=routes[id]+' · GNOT';}
function small(title,html){$('#small-title').textContent=title;$('#small-body').innerHTML=html;if(!$('#small-dialog').open)$('#small-dialog').showModal();}
function recordDetail(id){selectedId=id;const r=round(id);if(!r)throw Error('记录不存在，请重新载入。');const a=accounting(r),c=calculatePlan(r.plan);$('#record-title').textContent=r.symbol+' · 执行记录';$('#record-detail').innerHTML=`<div class="detail-meta"><span class="tag">${a.qty?'持仓中':'已退出'}</span><span class="tag">${r.scope==='history'?'旧持仓历史':r.executionModel?.mode==='atr-2r'?'结构/ATR · +2R':r.executionModel?'旧固定 −1R / +2R':'旧退出规则保留'}</span></div><div class="detail-summary"><div><span>剩余股数</span><strong>${a.qty}</strong></div><div><span>成本均价</span><strong>${price(a.avg)}</strong></div><div><span>已实现盈亏</span><strong>${money(a.realized)}</strong></div><div><span>实际 R</span><strong>${rval(a.r)}</strong></div></div><div class="target-row"><div><span>当前止损参考</span><strong>${price(Number.isFinite(effectiveStop(r))?effectiveStop(r):null)}</strong></div><div><span>退出参考</span><strong>${price(c.valid?c.target:null)}</strong></div></div><p class="field-note">初始 1R ${money(r.initialRisk)} · 参考参数按本笔保存；更正新规则买入时同步退出价与 R，旧记录保留原基准。</p><div class="saved-text"><p>买入理由：${esc(r.entryReason||'未填写')}</p><p>退出规则：${esc(r.exitPlan)}</p></div>${entryAuditHTML(r)}${a.qty?`<button class="primary-button" data-sell="${esc(r.id)}">记录卖出</button>`:''}<div class="detail-section"><h3>真实成交流水</h3><div class="table-wrap"><table><thead><tr><th>中国时间</th><th>方向</th><th class="num">股数</th><th class="num">实际价</th><th class="num">金额</th><th class="num">本次兑现</th><th></th></tr></thead><tbody>${a.rows.map(f=>`<tr><td>${esc(date(f.at))}</td><td>${kindText[f.kind]}</td><td class="num">${f.qty}</td><td class="num">${price(f.price)}</td><td class="num">${money(tradeAmount(f.qty,f.price))}</td><td class="num">${f.side==='sell'?money(f.pnl):'—'}</td><td><button class="table-action" data-edit-fill="${esc(f.id)}">更正</button><button class="table-action" data-delete-fill="${esc(f.id)}">删除</button></td></tr><tr><td colspan="7"><small>${esc(f.reason)}${f.violations.length?' · <span class="negative">'+f.violations.map(v=>esc(clean(v))).join('；')+'</span>':''}${f.unverified?.length?' · 待核对：'+f.unverified.map(esc).join('；'):''}</small></td></tr>`).join('')}</tbody></table></div></div>${a.qty?`<details class="compact-details"><summary>更新手动估值</summary><form id="mark-form" data-record-id="${esc(r.id)}"><div class="field-grid"><label>最新手动价格<input name="price" type="number" min="0.0001" step="0.0001" value="${r.mark?.price??''}" inputmode="decimal" required></label><label class="wide">价格中国时间<input name="at" type="datetime-local" step="1" value="${r.mark?timeInput(r.mark.at):nowInput()}" required></label></div><button class="secondary-button" type="submit">更新估值</button></form></details>`:''}<details class="compact-details" ${a.closed?'open':''}><summary>执行评价与复盘</summary><form id="review-form" data-record-id="${esc(r.id)}"><div class="field-grid"><label>规则执行自评<select name="compliant"><option value="unknown" ${r.review.compliant===null?'selected':''}>尚未评价</option><option value="yes" ${r.review.compliant===true?'selected':''}>遵守</option><option value="no" ${r.review.compliant===false?'selected':''}>偏离</option></select></label><label>自我评分<select name="rating">${[0,1,2,3,4,5].map(n=>`<option value="${n}" ${r.review.rating===n?'selected':''}>${n?n+' / 5':'尚未评分'}</option>`).join('')}</select></label></div><label class="full-field">本笔主要执行标签<select name="errorTag">${errorOptions(r.review.errorTag??'',{review:true})}</select></label><p class="field-note">空白表示尚未标注；守纪自评与标签分别记录。确认偏离标签计入违纪并沿用暂停规则；已确认标签保留。</p>${a.closed&&r.fills.some(f=>f.side==='sell'&&f.reasonCode==='stop')?`<label class="full-field">止损后下一完整交易日，是否重新出现完整买点<select name="stopReentry"><option value="pending" ${!r.review.stopReentry||r.review.stopReentry==='pending'?'selected':''}>待观察／待核对</option><option value="yes" ${r.review.stopReentry==='yes'?'selected':''}>手动核对：有新完整买点</option><option value="no" ${r.review.stopReentry==='no'?'selected':''}>手动核对：没有</option></select></label><p class="field-note">次一完整交易日收盘后填写；后来涨回来本身不等于新买点。</p>`:''}<label class="full-field">复盘备注<textarea name="notes" rows="4">${esc(r.review.notes)}</textarea></label><button class="secondary-button" type="submit">保存复盘</button></form></details>${r.stopEvents.length?`<details class="compact-details"><summary>原有止损调整记录</summary><div class="stop-list">${r.stopEvents.map(e=>esc(date(e.at))+' → '+price(e.price)+' · '+esc(e.reason)).join('<br>')}</div></details>`:''}<div class="danger-zone"><span class="field-note">修改保留上一版本机备份。</span><button id="delete-record" class="danger-button">删除本笔记录</button></div>`;if(!$('#record-dialog').open)$('#record-dialog').showModal();}
function sellDialog(id,editId=null){
  const r=round(id),a=accounting(r),old=editId?r.fills.find(f=>f.id===editId):null;if(!old&&!a.qty)throw Error('没有剩余股数。');selectedId=id;if($('#record-dialog').open)$('#record-dialog').close();const side=old?.side??'sell';
  small(old?'更正实际成交':r.symbol+' · 记录卖出',`<form id="fill-form" data-record-id="${esc(id)}" data-edit-id="${esc(editId??'')}" data-side="${side}"><div class="field-grid"><label>实际成交价<input name="price" type="number" min="0.0001" step="0.0001" inputmode="decimal" value="${old?.price??''}" required></label><label>成交股数<input name="qty" type="number" min="1" step="1" inputmode="numeric" value="${old?.qty??a.qty}" required></label></div><label class="full-field">成交金额<output id="fill-amount" class="amount-output">—</output></label>${side==='sell'?`<label class="full-field">卖出原因<select name="reasonCode">${Object.entries(reasonText).map(([k,v])=>`<option value="${k}" ${(old?.reasonCode??'target')===k?'selected':''}>${v}</option>`).join('')}</select></label>`:`<input name="reasonCode" type="hidden" value="${old?.reasonCode??'manual'}">`}<details class="compact-details"><summary>成交时间与备注</summary><label class="full-field">成交中国时间<input name="at" type="datetime-local" step="1" value="${old?timeInput(old.at):nowInput()}" required></label><label class="full-field">备注（可空）<input name="reason" maxlength="2000" value="${esc(old?.reason??'')}"></label></details><div id="fill-preview" class="fill-preview" aria-live="polite"></div><label id="fill-override" class="inline-check" hidden><input name="actualOverride" type="checkbox">成交已真实发生，保留偏离记录并如实登记</label><button class="primary-button full-width" type="submit">${old?'保存成交更正':'保存卖出记录'}</button><p class="field-note">默认全部退出，股数可按真实成交修改；不自动填写或假设实际卖出价。</p></form>`);updateFillPreview();
}
function fillInput(form){const v=values(form);return {...v,editId:form.dataset.editId||null,side:form.dataset.side,at:iso(v.at),reason:v.reason?.trim()||reasonText[v.reasonCode]||'实际成交'};}
function updateFillPreview(){const form=$('#fill-form');if(!form)return;const v=values(form),amount=tradeAmount(v.qty,v.price);$('#fill-amount').textContent=money(amount);$('#fill-override').hidden=true;if(amount===null){$('#fill-preview').textContent='填写实际成交价，金额自动换算。';return;}try{const p=prepareExecutionFill(state,form.dataset.recordId,fillInput(form));$('#fill-override').hidden=!p.check.pass;$('#fill-preview').innerHTML=`剩余 <strong>${p.check.after.qty} 股</strong> · 已实现 <strong>${money(p.check.after.realized)}</strong> / ${rval(p.check.after.r)}${p.check.violations.length?'<ul>'+p.check.violations.map(x=>'<li>'+esc(clean(x))+'</li>').join('')+'</ul>':'<p>实际金额与剩余股数已核对。</p>'}`;}catch(e){$('#fill-preview').textContent=clean(e.message);}}
function snapshotDialog(id=null){const s=id?state.snapshots.find(x=>x.id===id):null;small(s?'更正权益快照':'记录权益快照',`<form id="snapshot-form" data-id="${esc(id??'')}"><label class="full-field">快照中国时间<input name="at" type="datetime-local" step="1" value="${s?timeInput(s.at):nowInput()}" required></label><div class="field-grid"><label>实际账户总权益 USD<input name="equity" type="number" min="0.01" step="0.01" value="${s?.equity??''}" inputmode="decimal" required></label><label>距上一快照净出入金 USD<input name="flow" type="number" step="0.01" value="${s?.flow??0}" inputmode="decimal" required></label></div><p class="field-note">入金为正、出金为负，已包含在总权益内；无出入金填 0。统计起始日 ${esc(state.settings.startDate)}。</p><label class="full-field">依据／备注<input name="note" value="${esc(s?.note??'')}" required></label><button class="primary-button full-width" type="submit">保存快照</button></form>`);}
function download(text,name,type='application/json'){const url=URL.createObjectURL(new Blob([text],{type})),a=document.createElement('a');a.href=url;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),2000);}
async function exportData(mode='json'){if(!state)throw Error('请恢复本机数据或下载原始数据。');const stamp=new Date().toISOString().slice(0,10),copy=structuredClone(state);copy.meta.lastExport=new Date().toISOString();if(mode==='json')download(JSON.stringify(copy,null,2),'gnot-execution-'+stamp+'.json');else download(mode==='csv'?exportBackupCSV(copy):exportFillsCSV(copy),'gnot-execution-'+(mode==='csv'?'backup-':'fills-')+stamp+'.csv','text/csv;charset=utf-8');await commit(s=>s.meta.lastExport=copy.meta.lastExport,{backup:false});toast('已生成备份下载，请确认文件保存在设备中。');}
async function restore(data){const raw=localStorage.getItem(STORAGE_KEY);if(!state||storageError){state=await recoverStorage(data,raw);storageError=null;$('#storage-alert').hidden=true;}else await commit(s=>Object.assign(s,structuredClone(data)));hydrate();renderAll();status('已恢复至本机');}
async function importFile(file){if(!file)return;if(file.size>10*1024*1024)throw Error('备份超过 10 MB。');const raw=await file.text();pendingImport=file.name.toLowerCase().endsWith('.csv')?importBackupCSV(raw):validateState(JSON.parse(raw));$('#import-preview').innerHTML=`<div class="calc-status"><strong>文件校验通过</strong><p>${pendingImport.rounds.filter(r=>r.fills.length).length} 笔成交记录，当前数据尚未改变。</p></div><button id="confirm-import" class="primary-button">按所选方式导入</button>`;}
document.addEventListener('input',e=>{if(e.target.closest('#buy-form')){if(e.target.name==='equity'&&Number(e.target.value)>0)ensureWorkbench(state).equity=Number(e.target.value);scheduleDraft();}if(e.target.closest('#fill-form'))updateFillPreview();});
document.addEventListener('change',e=>{if(e.target.closest('#buy-form')){if(e.target.name==='equity'&&Number(e.target.value)>0)ensureWorkbench(state).equity=Number(e.target.value);scheduleDraft();}if(e.target.closest('#fill-form'))updateFillPreview();if(e.target.id==='journal-error'){journalError=e.target.value;renderJournal();}if(e.target.id==='performance-error'){performanceError=e.target.value;renderPerformance();}if(e.target.id==='journal-symbol'){journalSymbol=e.target.value;renderJournal();}if(e.target.id==='performance-symbol'){performanceSymbol=e.target.value;renderPerformance();}if(e.target.id==='trend-source-mode'){ensureWorkbench(state).trendModes??={};state.workbench.trendModes[state.draft.symbol]=e.target.value;scheduleDraft();renderAll();}if(e.target.id==='performance-version'){performanceVersion=e.target.value;renderPerformance();}if(e.target.id==='import-file')importFile(e.target.files[0]).catch(x=>{pendingImport=null;$('#import-preview').textContent=clean(x.message);});});
document.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;try{
  if(b.id==='refresh-trend-feed'){await syncTrendFeed(true);return;}
  if(b.id==='confirm-equity-day'){await commit(s=>{const w=ensureWorkbench(s);if(!(Number(w.equity)>0)||w.cash===''||!Number.isFinite(Number(w.cash)))throw Error('请先填写真实净值与可用现金。');w.equityDay=marketClock().day;});toast('已确认该美东日期的净值与现金。');return;}
  if(b.dataset.editRiskClose){small('更正收盘净值',closeForm(state,new Date().toISOString(),b.dataset.editRiskClose));return;}
  if(b.dataset.revokeRisk){small('重新复核恢复操作',`<form id="risk-revoke-form" data-id="${esc(b.dataset.revokeRisk)}"><p>更正数据使此前恢复条件不再成立。撤回该恢复操作后，系统重新按完整净值核对；原操作及撤回原因继续保留。</p><label class="full-field">数据更正原因<textarea name="notes" minlength="10" required></textarea></label><button type="submit" class="primary-button">撤回失效恢复并重新核对</button></form>`);return;}
  if(['risk-activate','risk-close','risk-normal','risk-restart','behavior-recovery'].includes(b.id)){if(b.id==='risk-activate')small('核对v1.1启用净值',activationForm(state,nowInput()));else if(b.id==='risk-close')small('登记收盘净值',closeForm(state));else {const kind=b.id==='risk-normal'?'normal':b.id==='risk-restart'?'restart':'behavior';small('恢复条件与复盘',recoveryForm(kind,state));}return;}
  if(b.dataset.close){$('#'+b.dataset.close).close();return;}
  if(b.dataset.symbol){if(busy||!state)return;busy=true;const controls=$$('#buy-form input, #buy-form button, [data-symbol]');controls.forEach(e=>e.disabled=true);try{readDraft();await commit(s=>Object.assign(s,selectDraft(s,b.dataset.symbol)),{render:false});hydrate();renderAll();}finally{controls.forEach(e=>e.disabled=!!storageError);busy=false;}return;}
  if(b.dataset.openRecord){recordDetail(b.dataset.openRecord);return;}if(b.dataset.sell){sellDialog(b.dataset.sell);return;}
  if(b.dataset.filter){journalFilter=b.dataset.filter;renderJournal();return;}if(b.dataset.editFill){sellDialog(selectedId,b.dataset.editFill);return;}
  if(b.dataset.deleteFill){if(!confirm('删除本次成交？后续股数与盈亏会重新核对。'))return;const id=selectedId;await commit(s=>{const r=s.rounds.find(r=>r.id===id);r.fills=r.fills.filter(f=>f.id!==b.dataset.deleteFill);accounting(r);});recordDetail(id);toast('成交已删除，相关金额与盈亏已重算。');return;}
  if(b.dataset.snapshot){snapshotDialog(b.dataset.snapshot);return;}if(b.dataset.deleteSnapshot){if(!confirm('删除这条权益快照？回撤结果会重新计算。'))return;await commit(s=>s.snapshots=s.snapshots.filter(x=>x.id!==b.dataset.deleteSnapshot));return;}
  if(b.dataset.backupDownload!==undefined){download(localBackups()[Number(b.dataset.backupDownload)].raw,'gnot-local-backup.json');return;}
  if(b.dataset.backupRestore!==undefined){const data=validateState(JSON.parse(localBackups()[Number(b.dataset.backupRestore)].raw));if(confirm('恢复这个版本并覆盖当前数据？建议先导出当前备份。'))await restore(data);return;}
  switch(b.id){
    case 'quick-export':case 'export-json':await exportData();break;
    case 'export-csv':await exportData('csv');break;case 'export-fills':await exportData('fills');break;
    case 'reload-data':location.reload();break;case 'download-raw':download(localStorage.getItem(STORAGE_KEY)||'null','gnot-original-data.json');break;
    case 'snapshot-button':if(!state.workbench.risk.baseline)small('核对v1.1启用净值',activationForm(state,nowInput()));else small('登记收盘净值',closeForm(state));break;
    case 'save-start-date':await commit(s=>{const d=$('#account-start-date').value;if(!d)throw Error('请选择有效日期。');s.settings.startDate=d;});toast('统计起始日已保存。');break;
    case 'drawdown-review-button':small('5% 回撤复核',`<form id="drawdown-review-form"><label class="full-field">复核结论<textarea name="notes" minlength="10" rows="4" required></textarea></label><p class="field-note">至少 10 字；10% 回撤不因复核而自动解除。</p><button class="primary-button" type="submit">保存复核</button></form>`);break;
    case 'delete-record':{const id=selectedId;if(!confirm('删除本笔交易及全部成交流水？上一版本机备份会保留。'))break;await commit(s=>s.rounds=s.rounds.filter(r=>r.id!==id));$('#record-dialog').close();selectedId=null;toast('记录已删除，上一版已保留。');break;}
    case 'confirm-import':if(!pendingImport)throw Error('请先选择有效备份。');if($('#import-mode').value==='replace'||!state||storageError){if(!confirm('整库恢复会覆盖当前数据，请先备份。确认继续？'))break;await restore(pendingImport);}else{await commit(s=>{const merged=mergeStates(s,pendingImport);s.rounds=merged.rounds;s.snapshots=merged.snapshots;s.drawdownReviews=merged.drawdownReviews;if(merged.workbench)s.workbench=merged.workbench;});}pendingImport=null;$('#import-preview').textContent='导入完成，请核对记录与权益。';break;
    case 'history-button':small('补录旧持仓',`<form id="history-form"><label class="full-field">历史标的<input name="symbol" maxlength="20" placeholder="RAM／IRE 等" required></label><div class="field-grid"><label>买入股数<input name="qty" type="number" min="1" step="1" required></label><label>实际买入价<input name="price" type="number" min="0.0001" step="0.0001" required></label></div><label class="full-field">买入中国时间<input name="at" type="datetime-local" step="1" value="${nowInput()}" required></label><label class="full-field">历史依据<input name="reason" required></label><p class="field-note">未知初始风险不虚构 R；历史分类排除主动统计。</p><button class="primary-button" type="submit">保存历史买入</button></form>`);break;
  }
}catch(error){toast(error.message,true);}});
document.addEventListener('submit',async e=>{
  const form=e.target;if(!['buy-form','fill-form','review-form','mark-form','snapshot-form','drawdown-review-form','history-form','recovery-form','risk-activate-form','risk-close-form','risk-recovery-form','risk-revoke-form'].includes(form.id))return;e.preventDefault();if(busy)return;busy=true;const button=form.querySelector('button[type="submit"]');if(button)button.disabled=true;
  try{const v=values(form);
    if(form.id==='buy-form'){readDraft();const input=buyInput();await commit(s=>{const p=prepareDisciplineBuy(s,input);if(!p.check.pass&&!form.elements.actualOverride.checked)throw Error('请核对风险提示，已发生时勾选如实登记。');s.rounds.push(p.round);ensureWorkbench(s).cash='';s.draft.reason='';delete s.draft.executionSnapshot;});form.elements.reason.value='';form.elements.at.value=nowInput();readDraft();location.hash='#workspace';$('#actual-recording').open=false;$('#open-positions').scrollIntoView({behavior:'smooth',block:'start'});toast('真实买入已保存，退出参考与初始 R 已冻结。');}
    if(form.id==='fill-form'){const input=fillInput(form);await commit(s=>{const p=prepareExecutionFill(s,form.dataset.recordId,input);if(!p.check.pass&&!form.elements.actualOverride.checked)throw Error('请核对偏离提示，已发生时勾选如实登记。');s.rounds=s.rounds.map(r=>r.id===p.round.id?p.round:r);if(p.round.executionModel?.mode==='atr-2r')ensureWorkbench(s).cash='';});$('#small-dialog').close();location.hash='#journal';toast('成交已保存，剩余股数与盈亏已更新。');}
    if(form.id==='review-form'){await commit(s=>{const r=s.rounds.find(r=>r.id===form.dataset.recordId),a=accounting(r),now=new Date().toISOString();if(v.stopReentry&&v.stopReentry!=='pending'){const day=nextTradingDay(marketClock(a.exitAt).day,{full:true}),end=day&&closingISO(day);if(!end||Date.parse(now)<Date.parse(end))throw Error('止损后的下一完整交易日收盘后，再确认是否重新出现完整买点。');}saveReview(r,v,now);if(v.stopReentry)Object.assign(r.review,{stopReentry:v.stopReentry,stopObservedAt:now});});recordDetail(form.dataset.recordId);toast('复盘已保存；已有偏离和待核对资料保留。');}
    if(form.id==='mark-form'){const at=iso(v.at);if(Date.parse(at)>Date.now()+60000)throw Error('手动估值时间不能在未来。');await commit(s=>s.rounds.find(r=>r.id===form.dataset.recordId).mark={price:Number(v.price),at});recordDetail(form.dataset.recordId);toast('手动估值已更新。');}
    if(form.id==='risk-revoke-form'){await commit(s=>revokeInvalidTransition(s,form.dataset.id,v.notes));$('#small-dialog').close();toast('已保留撤回记录，并重新核对风险档位。');}
    if(form.id==='risk-activate-form'){await commit(s=>activateRisk(s,{equity:Number(v.equity),at:iso(v.at),confirmed:!!v.confirmed}));$('#small-dialog').close();toast('v1.1启用净值已核对，旧记录保留。');}
    if(form.id==='risk-close-form'){const flows=(v.flows??'').split('\n').filter(x=>x.trim()).map(line=>{const [at,amount,equityBefore,...extra]=line.trim().split(/[｜|,，]/);if(extra.length||!at||amount===undefined||equityBefore===undefined)throw Error('出入金每行须为：北京时间｜金额｜发生前净值');return {at:iso(at.trim()),amount:Number(amount),equityBefore:Number(equityBefore)};});await commit(s=>form.dataset.editId?correctRiskClose(s,form.dataset.editId,{equity:Number(v.equity),flows,note:v.note}):addRiskClose(s,{day:v.day,equity:Number(v.equity),flows,note:v.note}));$('#small-dialog').close();toast('收盘净值已保存，风险档位已重算。');}
    if(form.id==='risk-recovery-form'){await commit(s=>{if(form.dataset.kind==='behavior'){const g=disciplineGuard(s);if(!g.trigger||!g.rested||!v.ordersChecked)throw Error('先完成规定休息期并处理违纪仓位与订单。');ensureWorkbench(s).recoveries.push({at:new Date().toISOString(),notes:v.notes.trim(),ordersResolved:true});}else transitionRisk(s,{kind:form.dataset.kind,notes:v.notes,cause:v.cause,ordersChecked:!!v.ordersChecked,causeResolved:!!v.causeResolved});});$('#small-dialog').close();toast('恢复条件通过，已保存复盘与档位操作。');}
    if(form.id==='snapshot-form'){const at=iso(v.at);if(Date.parse(at)>Date.now()+60000)throw Error('权益快照不能在未来。');const x={id:form.dataset.id||uid(),at,equity:Number(v.equity),flow:Number(v.flow),note:v.note};await commit(s=>{if(form.dataset.id)s.snapshots=s.snapshots.map(y=>y.id===x.id?x:y);else s.snapshots.push(x);});$('#small-dialog').close();toast('真实权益快照已保存。');}
    if(form.id==='drawdown-review-form'){if(v.notes.trim().length<10)throw Error('复核结论至少 10 字。');await commit(s=>s.drawdownReviews.push({id:uid(),at:new Date().toISOString(),notes:v.notes}));$('#small-dialog').close();toast('回撤复核已保存。');}
    if(form.id==='recovery-form'){if(v.notes.trim().length<10)throw Error('请填写至少10字的执行复盘。');await commit(s=>ensureWorkbench(s).recoveries.push({at:new Date().toISOString(),notes:v.notes.trim()}));$('#small-dialog').close();toast('恢复复盘已记录，休息期届满后恢复额度。');}
    if(form.id==='history-form'){const at=iso(v.at);if(Date.parse(at)>Date.now()+60000)throw Error('实际买入不能在未来。');await commit(s=>{const copy=structuredClone(s);copy.draft.plan={...copy.draft.plan,quantity:Number(v.qty),entry:Number(v.price),amount:tradeAmount(v.qty,v.price),stop:'',targetMode:'r',targetR:2,costs:0,gapPct:0};copy.draft.reason=v.reason;const r=newRound(copy,{scope:'history',symbol:v.symbol.toUpperCase()});r.entrySource='actual';const p=prepareExecutionFill({...s,rounds:[...s.rounds,r]},r.id,{side:'buy',qty:v.qty,price:v.price,at,reason:v.reason});s.rounds.push(p.round);});$('#small-dialog').close();location.hash='#journal';toast('历史买入已保存，未虚构初始 R。');}
  }catch(error){toast(error.message,true);}finally{busy=false;if(button?.isConnected)button.disabled=!!storageError;}
});
window.addEventListener('hashchange',()=>{route();window.scrollTo(0,0);});
window.addEventListener('storage',e=>{if(e.key===STORAGE_KEY)showStorageError('另一标签页更新了记录，请重新载入，避免覆盖。');});
document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='hidden'&&draftTimer&&state&&!storageError){readDraft();commit(()=>{},{backup:false,render:false}).catch(e=>toast(e.message,true));}});
workbench=mountWorkbench({getState:()=>state,onEdit:()=>scheduleDraft(),onUse:calc=>{state.draft.executionSnapshot={...structuredClone(calc.inputSnapshot??{}),entryCheck:captureEntryCheck(calc),...(calc.ready?{authorizedQty:calc.qty}:{})};const f=$('#buy-form');f.elements.price.value=calc.levels.entry;f.elements.qty.value=calc.ready?calc.qty:calc.referenceQty;f.elements.equity.value=calc.equity;f.elements.at.value=nowInput();$('#actual-recording').open=true;readDraft();renderBuy();$('#actual-recording').scrollIntoView({behavior:'smooth',block:'start'});scheduleDraft();},onRecovery:()=>small('连续亏损／违纪复盘',recoveryForm('behavior',state))});
setInterval(()=>{if(state){workbench.render(state.draft.symbol);renderGuard();renderHome();}},30000);
hydrate();route();renderAll();if(storageError){showStorageError(storageError);location.hash='#data';}else status(state.meta.updatedAt?'已保存至本机':'本机保存 · 尚无成交');

fetch(new URL('./TRADING_RULES.md',import.meta.url)).then(r=>{if(!r.ok)throw Error('规则读取失败');return r.text();}).then(md=>{$('#rule-references').innerHTML=referenceHTML(md);}).catch(()=>{$('#rule-references').innerHTML='<p>依据暂时未载入，请下载完整纪律MD阅读。</p>';});

let trendFetchBusy=false;
async function syncTrendFeed(manual=false){
  if(trendFetchBusy||!state||storageError)return;trendFetchBusy=true;
  const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),12000);
  try{
    const response=await fetch(TREND_FEED_URL+'?t='+Date.now(),{cache:'no-store',signal:controller.signal});
    if(!response.ok)throw Error('HTTP '+response.status);
    const changed=acceptTrendFeed(state,await response.json());delete state.workbench.trendFetchError;
    if(changed){await commit(()=>{},{backup:false,render:false});readDraft();renderAll();}
    else workbench?.render(state.draft.symbol);
    if(manual)toast('已读取最新已发布快照；这不会触发新的行情任务。');
  }catch(error){state.workbench.trendFetchError=error.name==='AbortError'?'读取超时':error.message;workbench?.render(state.draft.symbol);if(manual)toast('趋势同步失败：'+state.workbench.trendFetchError,true);}
  finally{clearTimeout(timer);trendFetchBusy=false;}
}
syncTrendFeed();
setInterval(()=>{if(document.visibilityState!=='hidden')syncTrendFeed();},60000);
document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible')syncTrendFeed();});
